), which is what the LLM suggested to you, but the syntax was incorrect:




TYPE OUTPUT_MAPPING_1 :
STRUCT
    Emergency: BIT;    // Qx.0
    Activation: BIT;   // Qx.1
    Conveyer: BIT;     // Qx.2

    {attribute 'hide'}
    _reserved1: BIT;
    {attribute 'hide'}
    _reserved2: BIT;
    {attribute 'hide'}
    _reserved3: BIT;

    Light: BIT;        // Qx.6
END_STRUCT
END_TYPE

PROGRAM PLC_PRG
VAR
